/* generated by tools/hh/banter_js.py from BANTER.md (approved by Erik, t598u). Do not edit by hand. */
var HH_BANTER = {"fierce":{"walk":[[["ryo","They’ve got a handheld out. I’m taking the match."],["aoi","{fast}It’s a game, Kazan. Not another door to kick in.{/fast}"],["ryo","Same stance. I still win from the front."]],[["ryo","They want a match. Good. I was getting restless."],["aoi","You treat every screen like a dare. That’s how first rounds drop."],["ryo","Then stop writing me off before I start."]],[["aoi","Watch their habits first. You can learn a pattern in the intro."],["ryo","I learn it when they hit the ground."],["aoi","{slow}That isn’t a plan.{/slow} It’s a hope with a button."]],[["ryo","Don’t lecture. I know how a fight works."],["aoi","A fight, on a two-inch screen. You hear yourself, Kazan?"],["ryo","I hear them waiting. That’s enough."]],[["aoi","You’re already leaning in. At least let them finish talking."],["ryo","They finished when they pulled the game out."],["aoi","That isn’t how a challenge works, and you know it."]],[["ryo","One match. I’ll keep it short."],["aoi","You always say short, then swing like it’s a real fight."],["ryo","It is to me. Don’t start."]],[["aoi","If you lose the first exchange, don’t take it out on the screen."],["ryo","I’m not going to lose the first exchange."],["aoi","That confidence is exactly what I’m talking about."]],[["ryo","They’re lined up for a game. Good. I’m bored of walking."],["aoi","Bored is how you get sloppy, Kazan."],["ryo","Then stay close and complain. I’m still starting it."]]],"named":{"sota":[["ryo","This is the kid who told us about the handheld. I’m starting with him."],["aoi","He did you a favor, and your first idea is to knock him down?"],["ryo","He asked for a match. That’s the favor."]],"rin":[["ryo","She looks half-asleep. This’ll be quick."],["aoi","She’s holding a Ronin, Kazan, not a pillow. Don’t get cute."],["ryo","I’m not cute. I’m starting."]],"kaito":[["ryo","Music Hall kid wants a match. He picked the sharp one."],["aoi","He already got cornered once today. Win without being the encore."],["ryo","I’ll win. I’m not doing a victory lap."]],"haru":[["ryo","First-year with the big one. I’ll put him down quick."],["aoi","He’s a first-year, Kazan, not a lieutenant. You hear how that sounded?"],["ryo","I hear a challenge. That’s all I need."]],"yuto":[["ryo","Yuto’s got my fighter on that screen."],["aoi","So you’re going to take it personally, of course."],["ryo","It’s my stance. I’m taking it back."]]},"super":[[["aoi","You spent the super the second it filled."],["ryo","That’s what it’s for."]],[["aoi","Loud. And completely untimed."],["ryo","They’re still on the ground."]],[["aoi","You didn’t even let the glow settle."],["ryo","Settling loses fights."],["aoi","It also loses bars you could have used later."]],[["aoi","Was that the plan, or did your thumb get excited?"],["ryo","It landed. That’s the plan."]],[["aoi","{fast}You spent it on a guess.{/fast}"],["ryo","A guess that hit."],["aoi","Don’t wink at me over a handheld, Kazan."]]],"low":[[["aoi","{fast}You’re eating every hit. Guard exists, Kazan.{/fast}"]],[["aoi","One more like that and the match is over."],["ryo","Then I end it first."]],[["aoi","You’re one hit from a reset and still walking forward."],["ryo","Forward is how I got this far."],["aoi","Forward is also how you got that red bar."]],[["aoi","{fast}Back up.{/fast} You’re not proving anything at that health."],["ryo","I’m proving I don’t back up."]],[["aoi","Guard, Kazan. Or enjoy losing with your chin out."],["ryo","I’ve got one burst left."],["aoi","Then don’t waste it on a tantrum."]]],"first":[[["ryo","First time against them. That’s a win."],["aoi","Your fighter ticked up. A quarter star. Did you notice, or just the knockout?"],["ryo","I noticed the knockout."]],[["ryo","New name, new win. The fighter got stronger."],["aoi","A quarter star. Try not to act like you invented winning."],["ryo","I invented this one."]],[["aoi","First time against them, and you still swung like you’d fought them all week."],["ryo","And they dropped. The star ticked. I’ll take both."],["aoi","I’ll give you the star. Not the speech."]],[["ryo","That’s a clean first win. Did you see the star?"],["aoi","I saw you almost drop the second exchange first."],["ryo","Almost doesn’t show on the star."]],[["aoi","A quarter star. That’s the fighter, not a medal for your ego."],["ryo","Same pocket. I’ll take it."],["aoi","Just don’t spend the rest of the day talking about it."]]],"rematch":[[["ryo","Same result. Told you."],["aoi","You won because they got sloppy, not because you listened."],["ryo","I’ll take sloppy."]],[["aoi","You swung through three openings you didn’t need."],["ryo","And they’re still down. Don’t start."]],[["ryo","Rematch, same ending."],["aoi","You’re getting comfortable. That’s when you start showing off."],["ryo","Showing off would have taken longer."]],[["aoi","You didn’t need that last super. You used it anyway."],["ryo","I had it. I spent it. They’re down."],["aoi","Save the leftover pride for someone who asked."]],[["ryo","They thought they had my timing. They didn’t."],["aoi","They had it until you got lucky in the corner."],["ryo","Luck still puts them down."]],[["aoi","You can stop looking at me like I should clap."],["ryo","A clap would be nice."],["aoi","Win quieter, Kazan. The win already happened."]]],"loss":[[["aoi","You charged the second the round started. They were waiting."],["ryo","I almost had them."],["aoi","Almost. You keep using that word like I should be impressed."]],[["ryo","One more. Right now."],["aoi","After you stop slamming buttons like they owe you."],["ryo","{fast}I wasn’t slamming them.{/fast}"]],[["aoi","They punished every jump. You kept jumping."],["ryo","Fine. I saw it."],["aoi","Seeing it after the loss is too late."]],[["ryo","That was cheap."],["aoi","Cheap is what you call a loss you caused."],["ryo","{fast}I didn’t cause the cheap part.{/fast}"]],[["aoi","You got angry in the last stretch and stopped thinking."],["ryo","I was trying to end it."],["aoi","You ended your own bar, Kazan."]],[["ryo","One more. I know what they do now."],["aoi","You knew in the third exchange too. Then you got impatient."],["ryo","So watch me not."]]],"glitch":{"ap":[[["ryo","So this is the one they wouldn’t talk about."],["aoi","He hid in the showers for a reason. Don’t rush just to prove you found him."],["ryo","I’m not proving anything. I’m playing him."]],[["ryo","Hidden in the showers. Of course I was going to play him."],["aoi","You sound proud of finding a boy behind a stall wall."],["ryo","I’m proud of finishing the list."]]],"win":[[["ryo","Even the cheater goes down."],["aoi","{slow}Double Shot.{/slow} Special twice. No recharge. That’s what he was sitting on."],["ryo","And a tournament at the arcade, later. I’ll be there."],["aoi","Of course you will. Try arriving with a plan."]],[["aoi","{slow}Double Shot.{/slow} Two specials, no wait. That’s his little secret."],["ryo","And a tournament later, real cabinets. I’m in."],["aoi","Of course you are. Try not to charge the registration table."]]],"loss":[[["ryo","He was firing twice. That’s not in the how-to."],["aoi","You saw it and kept swinging anyway. Next time, {slow}watch{/slow} first."]],[["ryo","Two shots before I could stand up. That’s cheating."],["aoi","You saw the second one coming and swung anyway. Next time, listen when I say wait."]]]}},"balanced":{"walk":[[["ryo","They look ready. I’ll keep it clean."],["aoi","Good. They asked for a match, not a beating, Kazan."],["ryo","It’s a game. I’ll win it. I won’t rub it in."]],[["aoi","Nervous hands. They’re proud of this game."],["ryo","Then I take the match seriously. They earned the challenge."],["aoi","I’ll be right here if the round goes long."]],[["ryo","Another challenger. You watching this one with me?"],["aoi","I was going to anyway. {quiet}Win or lose, I’m still here.{/quiet}"]],[["ryo","They look like they want this. I want it too."],["aoi","Then give them a fair one, Kazan. I’ll be right here."],["ryo","Fair. I can do fair."]],[["aoi","You’ve been looking forward to this. It’s all over your face."],["ryo","A little. Don’t make it a thing."],["aoi","I’m not. I like that you invited me to watch."]],[["ryo","If they get nervous, I won’t press the way I would in a real fight."],["aoi","Good. This is supposed to be fun for them too."],["ryo","Yeah. Fun. Then I still want the win."]],[["aoi","Go on. They’re waiting, and you already decided to be kind about it."],["ryo","Kind isn’t the same as going easy."],["aoi","I know the difference. I trust you to."]],[["ryo","Another match. Stay close?"],["aoi","I’m not going anywhere. Win clean, and I’ll be proud of that."],["ryo","I’ll try to give you that."]]],"named":{"sota":[["aoi","Arai-kun pointed us to this thing. Be decent to him, Kazan."],["ryo","I will. He earned a fair match."],["aoi","More than fair. He trusted you with a secret."]],"rin":[["aoi","Ueda-san just got those headphones off. Don’t make this another shock."],["ryo","I won’t. A quiet match. She can have the first move if she wants it."],["aoi","That’s the one I hoped you’d pick."]],"kaito":[["aoi","He’s had a long day in this hall. Keep it to the game, Kazan."],["ryo","I remember. Fair match, then we’re done."],["aoi","Fair is enough. He doesn’t need a speech after."]],"haru":[["aoi","This is the boy from the bread. He’s already had a scare today."],["ryo","I won’t add another. Clean match, then he’s done."],["aoi","Thank you. He picked a heavy fighter. That doesn’t make him a heavy person."]],"yuto":[["aoi","He came in here for quiet homework. A match is enough, not a storm."],["ryo","I’ll keep it clean. He can go back to the homework after."],["aoi","Please. He already had people shouting at him once."]]},"super":[[["aoi","There. You held it for the opening. Good."],["ryo","Figured you’d want me to wait."]],[["aoi","That’s the one. Don’t chase if it already landed."]],[["aoi","Patient. That was the right moment, Kazan."],["ryo","Didn’t want to waste it in their face for no reason."],["aoi","That’s why it landed clean."]],[["ryo","There. Held it till they stepped in."],["aoi","I saw. You waited for them, not just the bar."]],[["aoi","You spent it clean. No need to chase after."],["ryo","I was already stopping."]]],"low":[[["aoi","Easy, Kazan. You’ve got life left. Pick one clean hit."],["ryo","I’m still in it."]],[["aoi","{quiet}Stay with the match.{/quiet} You don’t have to swing wild to finish."]],[["aoi","You’re hurt, not finished. One careful swing is enough."],["ryo","I’ve got it. Thanks."],["aoi","I’m right here."]],[["ryo","It’s close."],["aoi","{quiet}I know.{/quiet} Stay with it. You don’t have to rush the end."]],[["aoi","Breathe, Kazan. The match isn’t over because the bar went red."],["ryo","Still standing."],["aoi","Then pick the next hit like you mean to keep standing."]]],"first":[[["ryo","First win on them. Felt fair."],["aoi","Your fighter gained a quarter star. That’s theirs now, and yours."],["ryo","We’ll take care of it."]],[["ryo","First time against them. Felt good. Fair, too."],["aoi","A quarter star. They helped you earn that, even in a loss."],["ryo","I’ll remember them for it."]],[["aoi","New name, and you didn’t rub it in. That’s the part I liked."],["ryo","The star’s a nice extra."],["aoi","Keep both. The manners and the star."]],[["ryo","They were shaking a little at the start. I tried not to make it worse."],["aoi","You didn’t. A quarter star, and they still might want to shake your hand."],["ryo","I’ll shake it."]],[["aoi","Your fighter grew a little. That’s a first-win star, Kazan."],["ryo","Ours, kind of."],["aoi","{slow}Ours is fine.{/slow}"]]],"rematch":[[["aoi","They almost had that last exchange. You let them finish their swing."],["ryo","Didn’t feel right to plow through it."],["aoi","{slow}That’s the part I wanted to see.{/slow}"]],[["ryo","Good match. They can have a rematch whenever."],["aoi","Tell them that. They’ll hear it better from you."]],[["aoi","You’re smiling. You can, you know. It’s allowed."],["ryo","Don’t make it a thing."],["aoi","I’m not. I’m just glad you’re glad."]],[["ryo","Second time, and they were better. Still wasn’t mean about it."],["aoi","I noticed. So did they."],["ryo","Good."]],[["aoi","You pulled back at the end when you didn’t have to."],["ryo","They were already done. No need to embarrass them."],["aoi","That’s the boy I wanted to walk with."]],[["ryo","Rematch win. I’ll thank them on the way out."],["aoi","Please. And I’ll wait while you do."]]],"loss":[[["ryo","I had it, then I didn’t."],["aoi","You played them with respect. That’s not why the round dropped."],["ryo","Yeah. They were better. One more, when they’re up for it."]],[["aoi","Hey. It’s a handheld, Kazan. You’re allowed to lose one."],["ryo","I know. Still stings."],["aoi","I’m still here. We can run it back when you’re ready."]],[["ryo","I got greedy at the end."],["aoi","Then we know what to hold next time. I’m not going anywhere."]],[["aoi","You don’t have to apologize to me. You played them honestly."],["ryo","Still wanted to win it for you."],["aoi","Win the next one for you. I’ll be there either way."]],[["ryo","They earned that. I don’t hate it. I just wanted it."],["aoi","Wanting it is fine, Kazan. We can ask for another when they’re ready."]],[["aoi","Hey. Look at me. This doesn’t change anything between us."],["ryo","I know. Helps to hear it anyway."],["aoi","Then I’ll say it as many times as you need."]]],"glitch":{"ap":[[["ryo","So this is the last one. Feels like he was waiting."],["aoi","He was. After five wins, he wanted a look at you. Be careful, not cruel."],["ryo","I’ll play him straight. Even if he doesn’t."]],[["aoi","Last one, tucked away in here. He looks like he’s been waiting a long time."],["ryo","I’ll play him straight. You stay close."],["aoi","I’m already close."]]],"win":[[["aoi","He slipped you a code. {slow}Double Shot.{/slow} Special twice, no wait."],["ryo","Feels like cheating."],["aoi","It’s a pocket code, not a stolen wallet. You can leave it unused."],["ryo","He also mentioned a tournament. Arcade cabinets. Later."],["aoi","We’ll go. Together. You don’t have to walk in alone."]],[["ryo","He handed us a code. Double Shot. Feels crooked."],["aoi","Then we don’t have to use it. The tournament news is enough."],["ryo","Arcade cabinets, later. We’ll go. Together."]]],"loss":[[["ryo","He hit me twice before I could recover."],["aoi","That’s his trick. You still played him fair."],["ryo","Next time I wait on the second. Stay with me on it."]],[["ryo","Two hits, no pause. I wasn’t ready for that."],["aoi","I know. You still didn’t get ugly about it."],["ryo","Next time, we take it slow and honest."]]]}},"strategic":{"walk":[[["aoi","The intro is long. That’s a tell if they skip it, or don’t."],["ryo","{brisk}If they skip, they’re impatient. I hold the first swing.{/brisk}"],["aoi","And if they watch it, we take the first move."]],[["ryo","New challenger. You seeing a stance?"],["aoi","Watch how they stand. If they inch forward, you keep them out."],["ryo","Special until they jump. Then I meet them in the air."]],[["aoi","Don’t show the super in the first exchange."],["ryo","{brisk}Hold the bar. Make them waste theirs.{/brisk}"],["aoi","Same read."]],[["aoi","Bar stays hidden until we see their first habit. Same read?"],["ryo","{brisk}Same read.{/brisk} I hold, you call the jump."],["aoi","I was about to say that. Try to leave me a line, Kazan."]],[["ryo","If they hide behind guard, I wait. If they rush, I meet them."],["aoi","Look at you, making a plan before the intro ends."],["ryo","I learned it from you. Don’t look so surprised."]],[["aoi","Don’t bite on the first special. That’s the bait more often than not."],["ryo","Second one, then I go. You’ll tap me if I’m early."],["aoi","I’ll tap you if you’re showing off, too."]],[["ryo","I’ve got their walk already."],["aoi","Do you, or do you have the walk you wanted them to have?"],["ryo","Fine. You call it, I’ll move."]],[["aoi","We’ll take the first exchange slow and steal the second."],["ryo","I was going to say the same thing."],["aoi","Then say it faster next time. I’m encouraging you, Kazan."]]],"named":{"sota":[["aoi","First name on the list, and he talks as loud as he plays."],["ryo","So I hold the first swing and let him show me everything."],["aoi","Same read. Try not to look grateful mid-round. It’ll distract him."]],"rin":[["aoi","Quiet players wait. If she picked the Ronin, she wants you to come to her."],["ryo","Then I don’t. I make her walk first."],["aoi","Good. Don’t mistake the yawn for a weakness, Kazan."]],"kaito":[["aoi","Razor Rei likes to press. Don’t give him the first miss for free."],["ryo","I check the rush, then I take my turn."],["aoi","Same read. Try to look like you thought of it yourself."]],"haru":[["aoi","He picked the heavy. Big, slow, and he wants you to get impatient."],["ryo","So I don’t. I wait, and I don’t dive in."],["aoi","Look at that. A plan that isn’t a headfirst dive. I’m proud, briefly."]],"yuto":[["aoi","He picked Kaze Tenma. That’s your habit, on his timer."],["ryo","So I watch for the things I would do, and I don’t do them first."],["aoi","Same read. If you fall for yourself, I’m going to laugh. Kindly."]]},"super":[[["aoi","{brisk}Now. That’s the opening.{/brisk}"],["ryo","That was your count."]],[["ryo","Bar’s full—"],["aoi","I was about to say spend it."]],[["aoi","{brisk}Late enough.{/brisk} I was going to scold you if you spent it earlier."],["ryo","I felt you about to."],["aoi","Good. Keep feeling it."]],[["ryo","Now—"],["aoi","Already nodding. That was a clean spend."],["ryo","Your count, my thumb."]],[["aoi","You held the bar like I asked, then used it better than I would have said."],["ryo","Write that down. I want it again later."],["aoi","Don’t push your luck. Once is praise."]]],"low":[[["aoi","Red. One safe special. Not a combo you can’t finish."],["ryo","On their next miss, then."]],[["aoi","They overreach when you’re low. Wait for the jump."],["ryo","Already waiting."]],[["aoi","Red. Don’t hero it. Walk, then one special on their miss."],["ryo","Same line I had."],["aoi","Then do it, and I’ll stop talking."]],[["ryo","One hit left in me, maybe two."],["aoi","Then don’t donate them. They’re going to jump. You know this."],["ryo","I know. I’m already waiting."]],[["aoi","{brisk}Guard the next one. Super after they miss, not in a panic.{/brisk}"],["ryo","After they miss. Same read."],["aoi","Same read. Now breathe."]]],"first":[[["ryo","First clear on them. The fighter ticked."],["aoi","A quarter star. That’s a clean stat up, not luck."],["ryo","Then we keep this one. Build it on new names only."]],[["aoi","Quarter star, first name. That’s a clean data point, not a fluke."],["ryo","So we keep the fighter, and we keep notes on them."],["aoi","I was already keeping notes. Try to keep up."]],[["ryo","First win. The star ticked when I waited."],["aoi","I saw you almost spend early. Then you didn’t. {brisk}Good ears.{/brisk}"]],[["aoi","New opponent, and you still used the plan we said in the walk-up."],["ryo","It worked. You can say I listened. Once."],["aoi","Once. Don’t get used to the applause."]],[["ryo","Quarter star. We earned that together."],["aoi","We did. Next time, try earning it a little sooner. I’m teasing."],["ryo","I know you are."]]],"rematch":[[["aoi","They telegraphed the special on the backward walk."],["ryo","So I walked forward. You called it a second earlier."],["aoi","{brisk}And you were already moving.{/brisk}"]],[["ryo","Two hits, then I held."],["aoi","Because the third would have bounced. Same line I had."]],[["aoi","They changed their first move. You didn’t follow the old one. Good."],["ryo","You kicked my shin when I started to."],["aoi","A gentle kick. You’re welcome."]],[["ryo","Same opponent, shorter match."],["aoi","Because you stopped showing them the super in the first ten seconds."],["ryo","Your lecture landed. Don’t look smug."]],[["aoi","Two for two. Careful, Kazan, you’re starting to look like you listen."],["ryo","I listen when the read is good."],["aoi","The read is good. I’ll allow the compliment."]],[["ryo","Called the backward walk again."],["aoi","And you were already moving. We’re getting consistent, which I like."],["ryo","Don’t make it sound like homework."]]],"loss":[[["aoi","You bit on the second special. The first was the bait."],["ryo","Won’t bite twice. Next time I wait, then hit back."],["aoi","I’ll tip you if they try that same gap."]],[["ryo","They changed timing on the last stretch."],["aoi","I saw. You were still fighting the first pattern."],["ryo","So we scrap that read and start from their late round."]],[["aoi","You were late on the jump by a breath."],["ryo","I felt it. Earlier on the next one."],["aoi","I’ll count it out loud if you want."]],[["aoi","You chased a bar you didn’t need and gave them the opening."],["ryo","I saw it late."],["aoi","Then we count that habit, and we don’t repeat it. I’m still with you."]],[["ryo","They had my jump timed."],["aoi","Because you jumped on the same breath three times. I’ll say I told you so kindly."]],[["aoi","That loss is useful. They only had one trick that worked."],["ryo","The delayed special. I bite that once."],["aoi","Once is allowed. Twice, I start charging interest."]]],"glitch":{"ap":[[["aoi","Last name on the list. And he picked a dead-end room."],["ryo","So he wanted the match after we’d learned the rest."],["aoi","{brisk}Watch for a rule that isn’t on the how-to.{/brisk}"]],[["ryo","Dead-end room, last name, and he wants a private match."],["aoi","Hidden rule, not a rush. You cut it off when I call it."],["ryo","Same read. I’ll try to look surprised."]]],"win":[[["aoi","There it is. {slow}Double Shot.{/slow} Two specials, no recharge."],["ryo","That’s the rule that wasn’t written down."],["aoi","Pocket it. One code a match. Don’t throw it in blind."],["ryo","He says the arcade’s running a tournament. Real cabinets."],["aoi","Then we scout the board before we enter. Same as here."]],[["aoi","{slow}Double Shot.{/slow} Two specials, no recharge. Write that down."],["ryo","Already written. And a tournament on real cabinets, later."],["aoi","Then we scout the board first. I’ll let you say “same as here.”"]]],"loss":[[["ryo","Second special came out before my first landed."],["aoi","Two specials, no wait. That’s the whole trick."],["ryo","Spend mine on the first, check the second. Same read."]],[["ryo","I knew the second shot was coming and still ate it."],["aoi","Knowing isn’t the same as waiting. I’m teasing, but I’m also right."],["ryo","Next time I wait. Same read, just later."]]]}}};
